mapper.select:
/* GroupMemberMapper.countByGroupIdAndStatus */
SELECT COUNT(*) FROM group_member
WHERE group_id = #{groupId} AND status = #{status}

/* GroupMemberMapper.findByGroupIdAndStatus */
SELECT 
FROM group_member gm
LEFT JOIN `user` u ON u.user_no = gm.user_no
WHERE gm.group_id = #{groupId} AND gm.status = #{status}

/* GroupMemberMapper.existsByGroupIdAndUserNoAndStatus */
SELECT COUNT(*) > 0
FROM group_member
WHERE group_id = #{groupId} AND user_no = #{userNo} AND status = #{status}

/* GroupMemberMapper.findGroupMemberById */
SELECT 
FROM group_member gm
LEFT JOIN `user` u ON u.user_no = gm.user_no
WHERE gm.id = #{id}

mapper.insert:
/* GroupMemberMapper.insertGroupMember */
INSERT INTO group_member (group_id, user_no, stdt_id, member_type, member_no, status, joined_at, created_by, updated_by, created_at, updated_at)
VALUES (#{groupId}, #{userNo}, #{stdtId}, #{memberType}, #{memberNo}, #{status}, #{joinedAt}, #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt})

mapper.select:
/* GroupMemberMapper.findMaxMemberNoByGroupId */
SELECT MAX(member_no) FROM group_member
WHERE group_id = #{groupId}

/* GroupMemberMapper.findByGroupIdAndUserNo */
SELECT 
FROM group_member gm
LEFT JOIN `user` u ON u.user_no = gm.user_no
WHERE gm.group_id = #{groupId} AND gm.user_no = #{userNo}
LIMIT 1

/* GroupMemberMapper.findByGroupId */
SELECT 
FROM group_member gm
LEFT JOIN `user` u ON u.user_no = gm.user_no
WHERE gm.group_id = #{groupId}
